TriggerOraclev10g.body:
DECLARE
  v_anteriores CLOB;
  v_nuevos     CLOB;
BEGIN
  IF UPDATING OR DELETING THEN
    SELECT JSON_OBJECT('ID_PRESTAMO' VALUE :OLD.ID_PRESTAMO, 'ID_USUARIO' VALUE :OLD.ID_USUARIO, 'ID_EJEMPLAR' VALUE :OLD.ID_EJEMPLAR, 'ID_BIBLIOTECARIO' VALUE :OLD.ID_BIBLIOTECARIO, 'FECHA_PRESTAMO' VALUE :OLD.FECHA_PRESTAMO, 'FECHA_DEVOLUCION_PREVISTA' VALUE :OLD.FECHA_DEVOLUCION_PREVISTA, 'ESTADO' VALUE :OLD.ESTADO) INTO v_anteriores FROM dual;
  END IF;
  IF INSERTING OR UPDATING THEN
    SELECT JSON_OBJECT('ID_PRESTAMO' VALUE :NEW.ID_PRESTAMO, 'ID_USUARIO' VALUE :NEW.ID_USUARIO, 'ID_EJEMPLAR' VALUE :NEW.ID_EJEMPLAR, 'ID_BIBLIOTECARIO' VALUE :NEW.ID_BIBLIOTECARIO, 'FECHA_PRESTAMO' VALUE :NEW.FECHA_PRESTAMO, 'FECHA_DEVOLUCION_PREVISTA' VALUE :NEW.FECHA_DEVOLUCION_PREVISTA, 'ESTADO' VALUE :NEW.ESTADO) INTO v_nuevos FROM dual;
  END IF;
  SP_REGISTRAR_BITACORA(
    'PRESTAMO',
    CASE WHEN INSERTING THEN 'INSERT' WHEN UPDATING THEN 'UPDATE' ELSE 'DELETE' END,
    NVL(:NEW.ID_PRESTAMO, :OLD.ID_PRESTAMO),
    v_anteriores,
    v_nuevos
  );
END;
